import urllib.request
import time


class RateLimitError(Exception):
    pass


class ServerError(Exception):
    pass


class ClientError(Exception):
    pass


class ConnectionError(Exception):
    pass


class APIClient:
    def __init__(self, base_url: str, timeout: int = 10):
        self.base_url = base_url
        self.timeout = timeout

    def get(self, path: str) -> str:
        url = self.base_url.rstrip('/') + '/' + path.lstrip('/')

        # Handle 4xx (except 429) immediately
        # We need to attempt the request first, but we can do a pre-check
        # Actually, we just make the request and handle errors.

        # Retry logic for 429
        for attempt in range(3):
            try:
                req = urllib.request.Request(url)
                with urllib.request.urlopen(req, timeout=self.timeout) as response:
                    body = response.read().decode('utf-8')
                    status = response.status
                    if status == 429:
                        # This shouldn't happen since we'd get an error, but handle it
                        if attempt < 2:
                            time.sleep(0.5 * (2 ** attempt))
                            continue
                        else:
                            raise RateLimitError("Rate limit exceeded")
                    elif status >= 500:
                        # Server error - retry once after 1s
                        if attempt == 0:
                            time.sleep(1)
                            continue
                        else:
                            raise ServerError(f"Server error: {status}")
                    elif status >= 400 and status != 429:
                        raise ClientError(f"Client error: {status}")
                    else:
                        return body
            except urllib.error.HTTPError as e:
                status = e.code
                if status == 429:
                    if attempt < 2:
                        time.sleep(0.5 * (2 ** attempt))
                        continue
                    else:
                        raise RateLimitError("Rate limit exceeded")
                elif status >= 500:
                    if attempt == 0:
                        time.sleep(1)
                        continue
                    else:
                        raise ServerError(f"Server error: {status}")
                elif status >= 400 and status != 429:
                    raise ClientError(f"Client error: {status}")
                else:
                    raise
            except urllib.error.URLError:
                # Network error - retry once after 1s
                if attempt == 0:
                    time.sleep(1)
                    continue
                else:
                    raise ConnectionError("Connection failed")

        # If we get here, something went wrong
        raise RateLimitError("Rate limit exceeded")
